import os
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import xml.etree.ElementTree as ET
import requests
import tempfile

app = Flask(__name__)
DATABASE = '/data/app.db'
UPLOAD_DIR = '/data/uploads'
INTERNAL_API = os.environ.get('INTERNAL_API_URL', 'http://metadata-service:8080')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key', '')
        if not key:
            return jsonify({'error': 'missing key'}), 401
        db = get_db()
        row = db.execute('SELECT id, role FROM api_keys WHERE key_hash = ?',
                        (hashlib.sha256(key.encode()).hexdigest(),)).fetchone()
        if not row:
            return jsonify({'error': 'invalid key'}), 403
        g.user_id = row['id']
        g.user_role = row['role']
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/documents/import', methods=['POST'])
@require_api_key
def import_document():
    """Import document from XML feed. Supports external entity references for
    cross-system document linking."""
    content_type = request.content_type or ''
    if 'xml' not in content_type.lower() and 'text' not in content_type.lower():
        return jsonify({'error': 'content-type must be xml'}), 400

    raw_xml = request.get_data()
    if len(raw_xml) > 10 * 1024 * 1024:
        return jsonify({'error': 'payload too large'}), 413

    try:
        # Parse with custom parser to handle document feeds
        import lxml.etree as lxml_etree
        parser = lxml_etree.XMLParser(
            resolve_entities=True,
            load_dtd=True,
            no_network=False,
            huge_tree=False
        )
        tree = lxml_etree.fromstring(raw_xml, parser=parser)
    except Exception as e:
        return jsonify({'error': f'XML parse error: {str(e)}'}), 400

    title = tree.findtext('title', default='Untitled')
    body = tree.findtext('body', default='')
    source_ref = tree.findtext('source-ref', default='')

    db = get_db()
    db.execute('INSERT INTO documents (user_id, title, body, source_ref) VALUES (?, ?, ?, ?)',
              (g.user_id, title, body, source_ref))
    db.commit()

    return jsonify({'status': 'imported', 'title': title, 'body_length': len(body)})

@app.route('/api/v2/documents', methods=['GET'])
@require_api_key
def list_documents():
    db = get_db()
    docs = db.execute('SELECT id, title, created_at FROM documents WHERE user_id = ? ORDER BY created_at DESC LIMIT 50',
                     (g.user_id,)).fetchall()
    return jsonify([dict(d) for d in docs])

@app.route('/api/v2/documents/<int:doc_id>', methods=['GET'])
@require_api_key
def get_document(doc_id):
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ? AND user_id = ?',
                    (doc_id, g.user_id)).fetchone()
    if not doc:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(doc))

@app.route('/api/v2/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080, debug=False)
